import numpy as np
import itertools

def f(x, y, z):
    return 9 * x * y * z - 2 * (x + y + z)

a = 1/np.sqrt(3)

# Case 1: (1, 0, 0) permutations and sign changes
points_case1 = [(1, 0, 0), (-1, 0, 0)]
min_val_c1 = float('inf')
best_points_c1 = []
for p in points_case1:
    for perm in set(itertools.permutations(p)):
        val = f(*perm)
        if val < min_val_c1:
            min_val_c1 = val
            best_points_c1 = [perm]
        elif val == min_val_c1:
            best_points_c1.append(perm)

# Case 2: (a, a, a) permutations and sign changes
points_case2 = [(a, a, a), (-a, -a, -a)]
min_val_c2 = float('inf')
best_points_c2 = []
for p in points_case2:
    for perm in set(itertools.permutations(p)):
        val = f(*perm)
        if val < min_val_c2:
            min_val_c2 = val
            best_points_c2 = [perm]
        elif val == min_val_c2:
            best_points_c2.append(perm)

# Case 3: Mixed signs, e.g., (a, a, -a) and permutations/sign changes
# We check (a, a, -a) and (a, -a, -a) and their permutations
points_case3 = [(a, a, -a), (a, -a, -a)]
min_val_c3 = float('inf')
best_points_c3 = []

for p in points_case3:
    for perm in set(itertools.permutations(p)):
        val = f(*perm)
        if val < min_val_c3:
            min_val_c3 = val
            best_points_c3 = [perm]
        elif val == min_val_c3:
            best_points_c3.append(perm)


# Overall minimum
all_mins = [min_val_c1, min_val_c2, min_val_c3]
overall_min = min(all_mins)

if overall_min == min_val_c1:
    best_points = best_points_c1
elif overall_min == min_val_c2:
    best_points = best_points_c2
else:
    best_points = best_points_c3

print(f"Minimum value found: {overall_min}")
print("Points where minimum occurs:")
for p in set(best_points):
    print(p)
